    size: 36e5,
    uploadedAt: "2026-07-17T12:00:00Z",
    text: `\u0627\u0644\u062A\u0631\u0628\u064A\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629 - \u0627\u0644\u0635\u0641 \u0627\u0644\u062A\u0627\u0633\u0639 \u0627\u0644\u0623\u0633\u0627\u0633\u064A - \u0627\u0644\u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u064A\u0645\u0646\u064A\u0629.
\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u062A\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u062A\u0639\u0644\u064A\u0645 - \u0642\u0637\u0627\u0639 \u0627\u0644\u0645\u0646\u0627\u0647\u062C \u0648\u0627\u0644\u062A\u0648\u062C\u064A\u0647.

\u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u0623\u0648\u0644\u0649: \u0627\u0644\u0639\u0642\u064A\u062F\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629 (\u0627\u0644\u0625\u064A\u0645\u0627\u0646 \u0628\u0627\u0644\u064A\u0648\u0645 \u0627\u0644\u0622\u062E\u0631 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649).
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0623\u0648\u0644: \u0627\u0644\u0645\u0648\u062A \u0648\u0627\u0644\u0628\u0639\u062B \u0648\u0627\u0644\u062D\u0633\u0627\u0628 \u0648\u0627\u0644\u062C\u0632\u0627\u0621 \u0648\u0627\u0644\u062C\u0646\u0629 \u0648\u0627\u0644\u0646\u0627\u0631 \u0643\u062D\u0642\u0627\u0626\u0642 \u062A\u0639\u0632\u0632 \u0627\u0644\u0639\u062F\u0627\u0644\u0629 \u0627\u0644\u0625\u0644\u0647\u064A\u0629 \u0627\u0644\u0645\u0637\u0644\u0642\u0629 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0627\u0644\u0623\u062E\u0644\u0627\u0642\u064A\u0629 \u0627\u0644\u0641\u0631\u062F\u064A\u0629.
\u0627\u0644\u0634\u0631\u062D \u0648\u0627\u0644\u0645\u0636\u0627\u0645\u064A\u0646: \u0627\u0644\u0625\u064A\u0645\u0627\u0646 \u0628\u0627\u0644\u064A\u0648\u0645 \u0627\u0644\u0622\u062E\u0631 \u064A\u063A\u0631\u0633 \u0641\u064A \u0646\u0641\u0633 \u0627\u0644\u0645\u0633\u0644\u0645 \u064A\u0642\u0638\u0629 \u0627\u0644\u0636\u0645\u064A\u0631 \u0627\u0644\u0645\u0633\u062A\u0645\u0631\u0629\u060C \u0648\u064A\u0639\u0644\u0645\u0647 \u0623\u0646 \u0643\u0644 \u062D\u0631\u0643\u0629 \u0648\u0633\u0643\u0648\u0646 \u0641\u064A \u0627\u0644\u062D\u064A\u0627\u0629 \u0627\u0644\u062F\u0646\u064A\u0627 \u0645\u0631\u0635\u0648\u062F\u0629 \u0648\u0645\u062D\u0627\u0633\u0628 \u0639\u0644\u064A\u0647\u0627\u060C \u0645\u0645\u0627 \u064A\u0642\u064A\u0647 \u0627\u0631\u062A\u0643\u0627\u0628 \u0627\u0644\u0638\u0644\u0645 \u0648\u0627\u0644\u0627\u0639\u062A\u062F\u0627\u0621 \u0639\u0644\u0649 \u062D\u0642\u0648\u0642 \u0648\u062D\u0631\u064A\u0627\u062A \u0627\u0644\u0622\u062E\u0631\u064A\u0646.
\u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0648\u062C\u062F\u0627\u0646\u064A\u0629: \u0627\u0644\u0637\u0645\u0623\u0646\u064A\u0646\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0648\u0627\u0644\u0631\u0636\u0627 \u0628\u0642\u0636\u0627\u0621 \u0627\u0644\u0644\u0647\u060C \u0648\u0627\u0644\u062D\u0631\u0635 \u0627\u0644\u0628\u0627\u0644\u063A \u0639\u0644\u0649 \u0627\u0633\u062A\u063A\u0644\u0627\u0644 \u0627\u0644\u0639\u0645\u0631 \u0641\u064A \u0639\u0645\u0627\u0631\u0629 \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u062E\u064A\u0631 \u0648\u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u062A\u062C\u0646\u0628 \u0627\u0644\u0639\u0628\u062B \u0648\u0627\u0644\u0639\u062F\u0645\u064A\u0629 \u0648\u0627\u0644\u0636\u064A\u0627\u0639 \u0627\u0644\u0631\u0642\u0645\u064A.

\u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629: \u0627\u0644\u0641\u0642\u0647 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062A\u064A \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A (\u0623\u062D\u0643\u0627\u0645 \u0627\u0644\u0628\u064A\u0639 \u0648\u062D\u0631\u0645\u0629 \u0627\u0644\u0631\u0628\u0627 \u0648\u0627\u0644\u063A\u0634).
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0623\u0648\u0644: \u0634\u0631\u0648\u0637 \u0635\u062D\u0629 \u0627\u0644\u0628\u064A\u0639 \u0628\u0627\u0644\u062A\u0631\u0627\u0636\u064A\u060C \u0648\u062D\u0631\u0645\u0629 \u0627\u0644\u0627\u062D\u062A\u0643\u0627\u0631 \u0648\u0627\u0644\u063A\u0634 \u0648\u0627\u0644\u0645\u062E\u0627\u062F\u0639\u0629 \u0641\u064A \u0627\u0644\u0645\u0643\u0627\u064A\u064A\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0632\u064A\u0646.
\u0627\u0644\u062A\u0637\u0628\u064A\u0642 \u0627\u0644\u062A\u0631\u0628\u0648\u064A \u0627\u0644\u0645\u0644\u0645\u0648\u0633: \u062A\u062D\u0644\u064A\u0644 \u0645\u0634\u0627\u0643\u0644 \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u064A\u0648\u0645\u064A\u0629 \u0648\u0639\u0642\u0648\u062F \u0627\u0644\u0628\u064A\u0639 \u0648\u0627\u0644\u0634\u0631\u0627\u0621 \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A\u0629 \u0641\u064A \u0627\u0644\u064A\u0645\u0646. \u063A\u0631\u0633 \u0623\u0647\u0645\u064A\u0629 \u0627\u0644\u0643\u0633\u0628 \u0627\u0644\u062D\u0644\u0627\u0644 \u0627\u0644\u0635\u0627\u062F\u0642\u060C \u0648\u0627\u0644\u062A\u062D\u0630\u064A\u0631 \u0627\u0644\u0634\u062F\u064A\u062F \u0645\u0646 \u0627\u0644\u063A\u0634 \u0648\u0627\u0644\u0631\u0628\u0627 \u0648\u0627\u0644\u0645\u0643\u0631 \u0628\u0627\u0644\u0632\u0628\u0627\u0626\u0646 \u0648\u0627\u0644\u062A\u0631\u0628\u062D \u063A\u064A\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.
\u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0648\u062C\u062F\u0627\u0646\u064A\u0629: \u0627\u0644\u0646\u0632\u0627\u0647\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0627\u0644\u0623\u062E\u0644\u0627\u0642\u064A\u0629\u060C \u0648\u0627\u0644\u0635\u062F\u0642 \u0648\u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0627\u0644\u0645\u0647\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0632\u0631\u0627\u0639\u0629 \u0648\u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0648\u0627\u0644\u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u0645\u0627\u062F\u064A\u0629.

\u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062B\u0627\u0644\u062B\u0629: \u0627\u0644\u0623\u062E\u0644\u0627\u0642 \u0648\u0627\u0644\u0633\u0644\u0648\u0643 (\u0627\u0644\u062D\u064A\u0627\u0621 \u0648\u0627\u0644\u0639\u0641\u0629 \u0648\u0627\u0644\u062A\u0648\u0627\u0636\u0639).
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0623\u0648\u0644: \u0627\u0644\u062D\u064A\u0627\u0621 \u0634\u0639\u0628\u0629 \u0645\u0646 \u0634\u0639\u0628 \u0627\u0644\u0625\u064A\u0645\u0627\u0646\u060C \u0648\u0623\u062B\u0631\u0647 \u0627\u0644\u0628\u0627\u0644\u063A \u0641\u064A \u0635\u064A\u0627\u0646\u0629 \u0643\u0631\u0627\u0645\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u062A\u0648\u0627\u0636\u0639\u0647 \u0644\u0644\u0622\u062E\u0631\u064A\u0646.
\u0627\u0644\u0634\u0631\u062D \u0648\u0627\u0644\u0628\u064A\u062F\u0627\u063A\u0648\u062C\u064A\u0627: \u0627\u0644\u062D\u064A\u0627\u0621 \u0647\u0648 \u062A\u0627\u062C \u0627\u0644\u0623\u062E\u0644\u0627\u0642 \u0627\u0644\u0630\u064A \u064A\u062D\u0641\u0638 \u0644\u0633\u0627\u0646 \u0627\u0644\u0637\u0627\u0644\u0628 \u0648\u0639\u064A\u0646\u0647 \u0648\u0642\u0644\u0628\u0647 \u0645\u0646 \u0627\u0644\u0633\u0642\u0648\u0637 \u0648\u0627\u0644\u0627\u0628\u062A\u0630\u0627\u0644 \u0648\u0627\u0644\u062A\u0647\u0627\u0641\u062A \u0639\u0644\u0649 \u0627\u0644\u0645\u062D\u062A\u0648\u064A\u0627\u062A \u0627\u0644\u0647\u0627\u0628\u0637\u0629\u060C \u0648\u064A\u063A\u0631\u0633 \u0641\u064A \u0646\u0641\u0633\u0647 \u0639\u0632\u0629 \u0627\u0644\u0646\u0641\u0633 \u0648\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629 \u0639\u0644\u0649 \u0627\u0644\u062D\u0631\u0645\u0627\u062A \u0648\u0627\u0644\u0623\u062F\u0628 \u0627\u0644\u0635\u0641\u064A \u0627\u0644\u0645\u0644\u0645\u0648\u0633.`
