    name: "\u0627\u0644\u0627\u062C\u062A\u0645\u0627\u0639\u064A\u0627\u062A - \u0627\u0644\u0635\u0641 \u0627\u0644\u0633\u0627\u0628\u0639 \u0627\u0644\u0623\u0633\u0627\u0633\u064A - \u0627\u0644\u062C\u0632\u0621 \u0627\u0644\u0623\u0648\u0644.pdf",
