    name: "\u0644\u063A\u062A\u064A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 - \u0627\u0644\u062C\u0632\u0621 \u0627\u0644\u062B\u0627\u0646\u064A - \u0627\u0644\u0635\u0641 \u0627\u0644\u0633\u0627\u0628\u0639 \u0627\u0644\u0623\u0633\u0627\u0633\u064A.pdf",
