    country: "\u0627\u0644\u064A\u0645\u0646",
    subject: "\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629",
    grade: "\u062C\u0645\u064A\u0639 \u0627\u0644\u0635\u0641\u0648\u0641 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0648\u0627\u0644\u062B\u0627\u0646\u0648\u064A\u0629",
    term: "\u062F\u0644\u064A\u0644 \u0627\u0644\u0645\u0639\u0644\u0645",
