    uploadedAt: "2026-07-17T12:00:00Z",
    text: `\u062F\u0644\u064A\u0644 \u0645\u0639\u0644\u0645 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0641\u064A \u062C\u0645\u064A\u0639 \u0627\u0644\u0635\u0641\u0648\u0641 \u0627\u0644\u0623\u0633\u0627\u0633\u064A\u0629 \u0648\u0627\u0644\u062B\u0627\u0646\u0648\u064A\u0629 - \u0627\u0644\u062C\u0645\u0647\u0648\u0631\u064A\u0629 \u0627\u0644\u064A\u0645\u0646\u064A\u0629.
\u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u062A\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u062A\u0639\u0644\u064A\u0645 - \u0642\u0637\u0627\u0639 \u0627\u0644\u0645\u0646\u0627\u0647\u062C \u0648\u0627\u0644\u062A\u0648\u062C\u064A\u0647 \u0648\u0627\u0644\u062A\u0639\u0644\u064A\u0645 \u0627\u0644\u0645\u0646\u0647\u062C\u064A.

\u0625\u0631\u0634\u0627\u062F\u0627\u062A \u0648\u062A\u0648\u062C\u064A\u0647\u0627\u062A \u0628\u064A\u062F\u0627\u063A\u0648\u062C\u064A\u0629 \u0648\u0634\u0627\u0645\u0644\u0629 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0635\u0641\u0648\u0641 (\u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u062B\u0627\u0646\u0648\u064A\u060C \u0627\u0644\u062B\u0627\u0646\u064A \u0627\u0644\u062B\u0627\u0646\u0648\u064A\u060C \u0648\u0627\u0644\u062B\u0627\u0644\u062B \u0627\u0644\u062B\u0627\u0646\u0648\u064A):
1. \u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A\u0627\u062A \u062A\u062F\u0631\u064A\u0633 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0645\u0646\u0627\u0647\u062C \u0627\u0644\u062B\u0627\u0646\u0648\u064A\u0629 \u0627\u0644\u0645\u0648\u062D\u062F\u0629:
- \u0627\u0644\u062A\u0639\u0644\u0645 \u0627\u0644\u062A\u0639\u0627\u0648\u0646\u064A\u060C \u0627\u0644\u0639\u0635\u0641 \u0627\u0644\u0630\u0647\u0646\u064A \u0627\u0644\u0641\u0644\u0633\u0641\u064A\u060C \u0648\u0627\u0644\u062A\u062D\u0644\u064A\u0644 \u0627\u0644\u0628\u0644\u0627\u063A\u064A \u0648\u0627\u0644\u0646\u0642\u062F\u064A \u0644\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0623\u062F\u0628\u064A\u0629 \u0627\u0644\u0645\u0639\u062A\u0645\u062F\u0629.
- \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0627\u0644\u062A\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629 \u0627\u0644\u062A\u0642\u0644\u064A\u062F\u064A\u0629 \u0648\u0627\u0644\u0643\u062A\u0627\u0628 \u0627\u0644\u0645\u0637\u0628\u0648\u0639 \u0648\u062A\u0646\u0645\u064A\u0629 \u0645\u0647\u0627\u0631\u0627\u062A \u0627\u0644\u0646\u0642\u062F \u0648\u0627\u0644\u0623\u062F\u0628 \u0648\u0627\u0644\u0628\u0644\u0627\u063A\u0629 \u0648\u0627\u0644\u062E\u0637.
- \u0631\u0628\u0637 \u062F\u0631\u0648\u0633 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0645\u0637\u0627\u0644\u0639\u0629 \u0628\u0627\u0644\u0647\u0648\u064A\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0648\u0627\u0644\u0645\u0648\u0631\u062B \u0627\u0644\u062B\u0642\u0627\u0641\u064A \u0648\u0627\u0644\u0633\u064A\u0627\u062F\u0629 \u0627\u0644\u0641\u0643\u0631\u064A\u0629 \u0648\u0627\u0644\u062A\u0631\u0627\u0628\u064A\u0629.

2. \u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0635\u0641 \u0627\u0644\u062B\u0627\u0646\u0648\u064A \u0648\u0627\u0644\u062D\u062F \u0645\u0646 \u0627\u0644\u0645\u0634\u062A\u062A\u0627\u062A:
- \u062D\u062B \u0627\u0644\u0637\u0644\u0627\u0628 \u0641\u064A \u0643\u0627\u0641\u0629 \u0627\u0644\u0645\u0631\u0627\u062D\u0644 \u0627\u0644\u062B\u0627\u0646\u0648\u064A\u0629 \u0639\u0644\u0649 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0635\u0627\u0645\u062A\u0629 \u0627\u0644\u0646\u0627\u0642\u062F\u0629 \u0648\u0627\u0644\u0643\u062A\u0627\u0628\u0629 \u0628\u062E\u0637 \u0627\u0644\u064A\u062F \u0644\u062A\u0646\u0634\u064A\u0637 \u0627\u0644\u062A\u0622\u0632\u0631 \u0627\u0644\u0639\u0635\u0628\u064A \u0648\u0627\u0644\u062D\u0633\u064A \u0627\u0644\u062D\u0631\u0643\u064A.

3. \u0623\u0633\u0627\u0644\u064A\u0628 \u0627\u0644\u062A\u0642\u0648\u064A\u0645 \u0648\u0627\u0644\u0627\u0645\u062A\u062D\u0627\u0646\u0627\u062A \u0627\u0644\u0648\u0637\u0646\u064A\u0629:
- \u0628\u0646\u0627\u0621 \u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u062A\u062D\u0635\u064A\u0644\u064A\u0629 \u0648\u0646\u0642\u062F\u064A\u0629 \u0645\u0633\u062A\u0645\u0631\u0629 \u062A\u0642\u064A\u0633 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0646\u062D\u0648\u064A \u0648\u0627\u0644\u0628\u0644\u0627\u063A\u064A \u0648\u0627\u0644\u0623\u062F\u0628\u064A \u0648\u062A\u063A\u0631\u0633 \u062D\u0628 \u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0648\u0627\u0644\u0627\u0639\u062A\u0632\u0627\u0632 \u0628\u0627\u0644\u0647\u0648\u064A\u0629.`
