    topic: "\u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u0633\u0627\u062F\u0633\u0629: \u0641\u064A \u0627\u0644\u0645\u0648\u0644\u062F \u0627\u0644\u0646\u0628\u0648\u064A (\u0634\u0639\u0631) \u0648\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0634\u0631\u0637",
    content: `\u0645\u0646\u0647\u062C \u0644\u063A\u062A\u064A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0644\u0644\u0635\u0641 \u0627\u0644\u062A\u0627\u0633\u0639 \u0627\u0644\u0623\u0633\u0627\u0633\u064A - \u0627\u0644\u062C\u0632\u0621 \u0627\u0644\u0623\u0648\u0644 - \u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u0633\u0627\u062F\u0633\u0629 (\u0641\u064A \u0627\u0644\u0645\u0648\u0644\u062F \u0627\u0644\u0646\u0628\u0648\u064A):
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0623\u0648\u0644: \u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u0627\u0633\u062A\u064A\u0639\u0627\u0628 \u0644\u0644\u0646\u0635 \u0627\u0644\u0634\u0639\u0631\u064A \u0641\u064A \u0630\u0643\u0631\u0649 \u0627\u0644\u0645\u0648\u0644\u062F \u0627\u0644\u0646\u0628\u0648\u064A \u0627\u0644\u0634\u0631\u064A\u0641 \u0648\u0627\u0644\u0627\u0642\u062A\u062F\u0627\u0621 \u0628\u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0643\u0631\u064A\u0645.
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0646\u064A: \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0646\u062D\u0648 - \u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0634\u0631\u0637 \u0648\u0623\u0631\u0643\u0627\u0646\u0647 \u0648\u0623\u062F\u0648\u0627\u062A \u0627\u0644\u0634\u0631\u0637 \u0627\u0644\u062C\u0627\u0632\u0645\u0629 \u0648\u063A\u064A\u0631 \u0627\u0644\u062C\u0627\u0632\u0645\u0629.
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0644\u062B: \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0625\u0645\u0644\u0627\u0621 - \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u0623\u0644\u0641 \u0627\u0644\u0644\u064A\u0646\u0629 \u0641\u064A \u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0648\u0627\u0644\u062D\u0631\u0648\u0641.`
