    topic: "\u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062A\u0627\u0633\u0639\u0629: \u0645\u062F\u064A\u0646\u0629 \u0634\u0628\u0627\u0645 (\u062D\u0636\u0631\u0645\u0648\u062A) \u0648\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u062A\u0639\u062C\u0628",
    content: `\u0645\u0646\u0647\u062C \u0644\u063A\u062A\u064A \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0644\u0644\u0635\u0641 \u0627\u0644\u062A\u0627\u0633\u0639 \u0627\u0644\u0623\u0633\u0627\u0633\u064A - \u0627\u0644\u062C\u0632\u0621 \u0627\u0644\u0623\u0648\u0644 - \u0627\u0644\u0648\u062D\u062F\u0629 \u0627\u0644\u062A\u0627\u0633\u0639\u0629 (\u0645\u062F\u064A\u0646\u0629 \u0634\u0628\u0627\u0645 \u062D\u0636\u0631\u0645\u0648\u062A):
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u0623\u0648\u0644: \u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u0627\u0633\u062A\u064A\u0639\u0627\u0628 \u0644\u0645\u0639\u0627\u0644\u0645 \u0645\u062F\u064A\u0646\u0629 \u0634\u0628\u0627\u0645 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0628\u0639\u0645\u0627\u0631\u0629 \u0646\u0627\u0637\u062D\u0627\u062A \u0627\u0644\u0633\u062D\u0627\u0628 \u0627\u0644\u0637\u064A\u0646\u064A\u0629 \u0627\u0644\u0641\u0631\u064A\u062F\u0629.
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0646\u064A: \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0646\u062D\u0648 - \u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u062A\u0639\u062C\u0628 \u0648\u0635\u064A\u063A\u062A\u0627\u0647 \u0627\u0644\u0642\u064A\u0627\u0633\u064A\u062A\u0627\u0646 (\u0645\u0627 \u0623\u0641\u0639\u064E\u0644\u064E\u0647\u060C \u0648\u0623\u0641\u0639\u0650\u0644 \u0628\u0647).
\u0627\u0644\u062F\u0631\u0633 \u0627\u0644\u062B\u0627\u0644\u062B: \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0625\u0645\u0644\u0627\u0621 - \u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0639\u0644\u0649 \u0627\u0644\u062D\u0630\u0641 \u0641\u064A \u0622\u062E\u0631 \u0627\u0644\u0643\u0644\u0645\u0629.`
