    topic: "\u0627\u0644\u0641\u062E\u0631 \u0628\u0627\u0644\u0623\u062C\u062F\u0627\u062F \u0648\u062D\u0636\u0627\u0631\u0629 \u0633\u0628\u0623 \u0648\u062D\u0645\u064A\u0631",
    content: `\u0645\u0646\u0647\u062C \u0627\u0644\u0645\u0637\u0627\u0644\u0639\u0629 \u0648\u0627\u0644\u0628\u0644\u0627\u063A\u0629 \u0644\u0644\u0635\u0641 \u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u062B\u0627\u0646\u0648\u064A - \u062D\u0636\u0627\u0631\u0629 \u0633\u0628\u0623 \u0648\u0645\u0639\u062C\u0632\u0629 \u0633\u062F \u0645\u0623\u0631\u0628:
\u0633\u0637\u0631 \u0627\u0644\u064A\u0645\u0627\u0646\u064A\u0648\u0646 \u0627\u0644\u0642\u062F\u0627\u0645\u0649 \u0639\u0644\u0649 \u062C\u062F\u0631\u0627\u0646 \u0627\u0644\u0635\u062E\u0648\u0631 \u0627\u0644\u0634\u0627\u0645\u062E\u0629 \u0628\u062E\u0637 \u0627\u0644\u0645\u0633\u0646\u062F \u062A\u0627\u0631\u064A\u062E\u0627\u064B \u0645\u062C\u064A\u062F\u0627\u064B \u064A\u0642\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u0639\u0645\u0627\u0631 \u0648\u0627\u0644\u062A\u062D\u0643\u0645 \u0627\u0644\u0630\u0643\u064A \u0628\u0627\u0644\u0645\u064A\u0627\u0647 \u062F\u0648\u0646 \u062A\u062F\u0645\u064A\u0631 \u0644\u0644\u0628\u064A\u0626\u0629 \u0627\u0644\u0637\u0628\u064A\u0639\u064A\u0629. \u0625\u0646 \u062F\u0631\u0627\u0633\u0629 \u062D\u0636\u0627\u0631\u0629 \u0633\u0628\u0623 \u0648\u062D\u0645\u064A\u0631 \u062A\u062F\u0639\u0648 \u0627\u0644\u0637\u0627\u0644\u0628 \u0644\u0644\u0627\u0639\u062A\u0632\u0627\u0632 \u0628\u0647\u0648\u064A\u062A\u0647 \u0627\u0644\u0645\u0627\u062F\u064A\u0629 \u0648\u062A\u0627\u0631\u064A\u062E \u0623\u062C\u062F\u0627\u062F\u0647 \u0627\u0644\u0630\u064A\u0646 \u0634\u064A\u062F\u0648\u0627 \u0627\u0644\u0642\u0635\u0648\u0631 \u0627\u0644\u0634\u0627\u0647\u0642\u0629 \u0648\u0632\u0631\u0639\u0648\u0627 \u0627\u0644\u0645\u062F\u0631\u062C\u0627\u062A \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0628\u0623\u064A\u062F\u064A\u0647\u0645 \u0627\u0644\u0633\u0645\u0631\u0627\u0621 \u0627\u0644\u0642\u0648\u064A\u0629.
\u064A\u062A\u0639\u0644\u0645 \u0627\u0644\u0637\u0627\u0644\u0628 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u062F\u0631\u0633:
1. \u0627\u0644\u062C\u0630\u0648\u0631 \u0627\u0644\u062A\u0627\u0631\u064A\u062E\u064A\u0629 \u0648\u0627\u0644\u062B\u0642\u0627\u0641\u064A\u0629 \u0644\u0644\u064A\u0645\u0646 \u0648\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0633\u064A\u0627\u062F\u0629 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u0632\u0631\u0627\u0639\u0629.
2. \u0639\u0644\u0645 \u0627\u0644\u0645\u0639\u0627\u0646\u064A: \u0623\u0633\u0627\u0644\u064A\u0628 \u0627\u0644\u062A\u0648\u0643\u064A\u062F \u0627\u0644\u0644\u0641\u0638\u064A \u0648\u0627\u0644\u0645\u0639\u0646\u0648\u064A \u0648\u062C\u0645\u0627\u0644\u064A\u0627\u062A \u0627\u0644\u0625\u064A\u062C\u0627\u0632 \u0627\u0644\u0641\u0635\u064A\u062D \u0641\u064A \u0646\u0642\u0648\u0634 \u0627\u0644\u0645\u0633\u0646\u062F.
3. \u062A\u0631\u0633\u064A\u062E \u0637\u0645\u0648\u062D \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u064A\u062F\u0648\u064A \u0627\u0644\u0641\u0639\u0644\u064A \u0648\u0627\u0644\u0627\u0628\u062A\u0639\u0627\u062F \u0639\u0646 \u0627\u0644\u062A\u0643\u0627\u0633\u0644 \u0648\u0627\u0644\u0644\u0647\u0627\u062B \u0648\u0631\u0627\u0621 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0629.`
